require "rails_helper"

RSpec.describe "Timekeeping internal handoff checkpoint" do
  include_context "timekeeping entry writes without transactional fixtures"

  around do |example|
    with_handoff_env(public_key: false) { example.run }
  end

  # "A monolith row with a source such as "agent" is therefore stored in
  # Timekeeping's entries table, and any later write republishes it to the
  # outbox, where the projection refuses it and delivery stops."
  it "refuses a checkpoint load whose entry source is outside the contract with 400 invalid_request, echoes no row value and stores nothing" do
    expect(Timekeeping::SnapshotValues::SOURCES).not_to include("agent")
    Entry.create!(company_id: 1, user_id: 7, project_id: 3, work_date: "2026-03-02", duration: 90.0,
                  note: "kept", bill_status: "unbilled", source: "manual", source_metadata: {})
    Timekeeping::Admission.fence!
    before = handoff_stored_rows

    good = handoff_checkpoint_tables(company_id: 1, id: 7)
    bad = handoff_checkpoint_tables(company_id: 2, id: 8, overrides: {
      "entries" => { "source" => "agent", "note" => "private-load-note" }
    })
    checkpoint = Timekeeping::Handoff::Checkpoint.build(tables: merge_handoff_checkpoint_tables(good, bad))

    handoff_request(:checkpoint_load, body: checkpoint.to_json)

    expect(response.status).to eq(400)
    expect(response.parsed_body).to eq("reason" => "invalid_request")
    # The refusal answers with a reason only, so no row value reaches the caller.
    expect(response.body).not_to include("private-load-note")
    expect(response.body).not_to include("agent")
    expect(handoff_stored_rows).to eq(before)
    expect(Entry.where(source: "agent")).to be_empty
  end
end

